# NorMuon optimizer


class NorMuon(torch.optim.Optimizer):
    """
    Muon - MomentUm Orthogonalized by Newton-schulz

    https://kellerjordan.github.io/posts/muon/

    Muon internally runs standard SGD-momentum, and then performs an orthogonalization post-
    processing step, in which each 2D parameter's update is replaced with the nearest orthogonal
    matrix. To efficiently orthogonalize each update, we use a Newton-Schulz iteration, which has
    the advantage that it can be stably run in bfloat16 on the GPU.

    Warning: This optimizer should not be used for the embedding layer, the final fully connected layer,
    or any {0,1}-D parameters; those should all be optimized by a standard method (e.g., AdamW).

    Differences from standard Muon:
    - Newton-Shulz is replaced with Polar Express for the orthogonalization step
    - NorMuon adds a low-rank variance estimator similar to Adafactor. https://arxiv.org/pdf/2510.05491
    - small 1D parameters handled here instead of in Adam
    - Cautious weight decay, a gated version of decoupled weight decay
    - Custom distributed sizing:
    The model stores all attn and mlp weights in the same shape, and then updates the view as
    needed on the forward pass. This enables attn and mlp weights to be contained within the same
    dist.reduce_scatter_tensor() call. The model architecture has been customized to enable
    (n_attn_layers+n_mlp_layers*2)%8==0 for batching across 8 GPUs with zero padding on mlp and attn.
    The scheduling is:
        1. reduce scatter attn_gate (10 params 6 padding params)
        2. reduce scatter attn/mlp round 1 (10 attn params 6 mlp params)
        3. reduce scatter attn/mlp round 2 (16 mlp params)
        4. wait on step 1, then compute update of 1 and schedule all gather
        5. wait on step 2, then compute update of 2 and schedule all gather
        6. wait on step 3, then compute update of 3 and schedule all gather
            GPUs receive [2 ATTN, 2 ATTN, 2 ATTN, 2 ATTN, 2 ATTN, 2 MLP, 2 MLP, 2 MLP]
            GPUs that receive params of type attn reshape before computing update
        7. wait on 4, then compute update of 4 and schedule all gather
        8. wait for each all gather to complete and update params
    Empirically, leading with small params provides an additional 0.2s improvement.
    """

    def __init__(
        self,
        params,
        lr=0.02,
        weight_decay=0.01,
        momentum=0.95,
        beta2=0.95,
        custom_sizing=True,
        group=None,
    ):
        defaults = dict(
            lr=lr, weight_decay=weight_decay, momentum=momentum, beta2=beta2
        )
        # group: a single-rank group for rank-local params (sharded MoE experts: whole experts per rank)
        self.group = group
        self.world_size = dist.get_world_size(group) if dist.is_initialized() else 1
        # custom sizing requires 8 GPUs and the upstream 16-layer matrices
        params = list(params)
        layout = dict(attn_gate=16, value_embed_gate=10, attn=16, mlp=32)
        if (
            custom_sizing
            and dist.get_world_size() == 8
            and Counter(p.label for p in params) == layout
        ):
            param_groups = self.generate_custom_param_groups(params)
        else:
            param_groups = self.generate_standard_param_groups(params)
        super().__init__(param_groups, defaults)
        # BF16 weights (p.master): FP32 master of this rank's shard from the FP32 init, FP32 grads in one
        # padded stacked buffer per group (reduce-scattered in place) and the BF16 params as rows of
        # another (all-gathered in place)
        rank = dist.get_rank(group) if dist.is_initialized() else 0
        self._flat, self._pflat = {}, {}
        for i, group in enumerate(self.param_groups):
            ps, lo = group["params"], rank * group["chunk_size"]
            if not getattr(ps[0], "master", False):
                continue
            if lo < len(ps):
                group["master"] = torch.stack(
                    [p.fp32 for p in ps[lo : lo + group["chunk_size"]]]
                )
            shape = (group["chunk_size"] * self.world_size, *ps[0].shape)
            self._flat[i] = torch.zeros(shape, dtype=torch.float32, device=ps[0].device)
            self._pflat[i] = torch.zeros(shape, dtype=ps[0].dtype, device=ps[0].device)
            for k, p in enumerate(ps):
                self._pflat[i][k].copy_(p.detach())
                p.data, p.main_grad, p.fresh = self._pflat[i][k], self._flat[i][k], True
                del p.fp32
        # by index: load_state_dict replaces the group dicts
        self._group_of = {
            p: i for i, g in enumerate(self.param_groups) for p in g["params"]
        }

    def reset(self):
        # expose a reset for clearing buffers
        for group in self.param_groups:
            if "momentum_buffer" in group:
                group["momentum_buffer"].zero_()
                group["second_momentum_buffer"].zero_()

    def generate_standard_param_groups(self, params):
        """
        Use this method if running on less than 8 GPU or experimenting with additional attn or mlp modules.
        Creates one param group per module.
        """
        groups = defaultdict(list)
        for param in params:
            groups[param.label].append(param)

        param_groups = []
        for module_name, group_params in groups.items():
            chunk_size = (len(group_params) + self.world_size - 1) // self.world_size
            param_groups.append(dict(params=group_params, chunk_size=chunk_size))

        return param_groups

    def generate_custom_param_groups(self, params):
        """
        Implementation requires that a single GPU does not receive both attn
        and mlp params when a param group is split across GPUs.
        """
        params_list = list(params)
        module_group_order = [
            "attn_gate",
            "value_embed_gate",
            "attn",
            "mlp",
        ]  # 16, 10, 16, 32
        group_sizes = [16, 10, 16, 16, 16]
        params_list.sort(key=lambda x: module_group_order.index(x.label))
        print0(len(params_list), console=True)
        idx = 0
        assert len(params_list) == sum(group_sizes)
        param_groups = []
        for size in group_sizes:
            chunk_size = (size + self.world_size - 1) // self.world_size
            group_params = params_list[idx : idx + size]
            param_groups.append(dict(params=group_params, chunk_size=chunk_size))
            idx += size

        return param_groups

    @torch.no_grad()
    def step(self):
        # Efficient distributed step by @YouJiacheng, @KonstantinWilleke, @alexrgilbert,
        # @adricarda, @tuttyfrutyee, @vdlad, @ryanyang0, @vagrawal, @varunneal, @chrisjmccormick
        rank = dist.get_rank(self.group)
        group_infos = []
        for group in self.param_groups:
            params: list[Tensor] = group["params"]
            if not params:
                continue

            chunk_size = group["chunk_size"]
            flat = self._flat.get(self._group_of[params[0]])
            if flat is not None:  # BF16 weights: FP32 grads already stacked
                for p in params:
                    p.fresh = True  # the next accumulation overwrites, after this reduce-scatter
                grad_chunk = torch.empty_like(flat[:chunk_size])
                reduce_future = dist.reduce_scatter_tensor(
                    grad_chunk, flat, op=dist.ReduceOp.AVG, group=self.group,
                    async_op=True,
                )
                group_infos.append(
                    dict(grad_chunk=grad_chunk, reduce_future=reduce_future)
                )
                continue
            padded_num_params = chunk_size * self.world_size

            stacked_grads = torch.empty(
                (padded_num_params, *params[0].shape),
                dtype=params[0].dtype,
                device=params[0].device,
            )
            for i, p in enumerate(params):
                stacked_grads[i].copy_(p.grad, non_blocking=True)
            if len(params) < padded_num_params:
                stacked_grads[len(params) :].zero_()

            grad_chunk = torch.empty_like(stacked_grads[:chunk_size])

            reduce_future = dist.reduce_scatter_tensor(
                grad_chunk, stacked_grads, op=dist.ReduceOp.AVG, group=self.group,
                async_op=True,
            )

            group_infos.append(dict(grad_chunk=grad_chunk, reduce_future=reduce_future))

        all_gather_infos = []
        # Second pass: wait for gradients, compute updates for the local shard of parameters,
        # and launch all async all_gather operations.
        for group, info in zip(self.param_groups, group_infos):
            info["reduce_future"].wait()

            params = group["params"]
            grad_chunk = info["grad_chunk"]
            # BF16 weights: FP32 grads, momentum and update math on the FP32 master
            master = getattr(params[0], "master", False)
            chunk_size = group["chunk_size"]
            padded_num_params = chunk_size * self.world_size

            start_idx = rank * chunk_size
            module_idx = start_idx if start_idx < len(params) else 0

            num_params = min(
                chunk_size, max(0, len(params) - start_idx)
            )  # num params for this rank

            if "momentum_buffer" not in group:
                group["momentum_buffer"] = torch.zeros_like(grad_chunk[:num_params])
            momentum_buffer = group["momentum_buffer"]
            # Apply momentum update to the persistent momentum buffer in-place
            momentum_buffer.lerp_(grad_chunk[:num_params], 1 - group["momentum"])
            updated_grads = grad_chunk[:num_params].lerp_(
                momentum_buffer, group["momentum"]
            )

            grad_shape = updated_grads.shape
            if params[module_idx].label == "attn":
                for p in params[module_idx : module_idx + num_params]:
                    assert p.label == "attn"

                updated_grads = updated_grads.view(
                    4 * grad_shape[0], grad_shape[1] // 4, grad_shape[2]
                )

            ref_param = params[module_idx]
            param_shape = ref_param.shape

            # The below shape-based heuristic assumes that matrices have their input along the
            # row dimension and their output along the columns. Gates are an exception.
            is_gate = "gate" in ref_param.label

            if "second_momentum_buffer" not in group:
                if is_gate:
                    group["second_momentum_buffer"] = torch.zeros_like(
                        updated_grads[..., :, :1]
                    )
                else:
                    group["second_momentum_buffer"] = (
                        torch.zeros_like(updated_grads[..., :, :1])
                        if param_shape[-2] >= param_shape[-1]
                        else torch.zeros_like(updated_grads[..., :1, :])
                    )
            second_momentum_buffer = group["second_momentum_buffer"]

            if "param_lr_cpu" not in group:
                # Define multipliers for ALL params in this group (global, not per-shard)
                lr_mults = []
                wd_mults = []
                for p in params:
                    # Increase learning rate for modules with larger inputs than outputs.
                    # This shape check also assumes rows=input, columns=output, so take care
                    # when changing memory layouts. @chrisjmccormick
                    shape = p.shape
                    if len(shape) >= 2:
                        shape_mult = max(1.0, shape[-2] / shape[-1]) ** 0.5
                    else:
                        shape_mult = 1.0
                    lr_mults.append(shape_mult * getattr(p, "lr_mul", 1.0))
                    wd_mults.append(getattr(p, "wd_mul", 1.0))
                # Define as cpu tensors to enable Inductor constant folding
                group["param_lr_cpu"] = torch.tensor(
                    lr_mults, dtype=torch.float32, device="cpu"
                )
                group["param_wd_cpu"] = torch.tensor(
                    wd_mults, dtype=torch.float32, device="cpu"
                )

            eff_lr_all = group["param_lr_cpu"] * group["lr"]
            eff_wd_all = group["param_wd_cpu"] * group["weight_decay"] * group["lr"]

            # Slice the portion corresponding to this rank's shard
            eff_lr_cpu = eff_lr_all[module_idx : module_idx + num_params]
            eff_wd_cpu = eff_wd_all[module_idx : module_idx + num_params]

            # Compute zeropower for the entire chunk in a single, batched call.
            if num_params == 0:
                v_chunk = updated_grads
            else:
                v_chunk = polar_express(  # 3D params (MoE experts): one matrix per leading index
                    updated_grads.flatten(0, -3), split_baddbmm=(ref_param.label == "mlp")
                ).view(updated_grads.shape)

            # Note that the head orientation in O is transposed relative to QKV, so red_dim
            # is 'incorrect' for O. However, correcting this showed no improvement. @chrisjmccormick
            red_dim = -1 if (is_gate or param_shape[-2] >= param_shape[-1]) else -2

            if NORMUON:
                v_chunk = apply_normuon_variance_reduction(
                    v_chunk, second_momentum_buffer, group["beta2"], red_dim
                )

            v_chunk = v_chunk.view(grad_shape)

            # # "Cautious" weight decay (https://arxiv.org/abs/2510.12402)
            updated_params = torch.empty_like(grad_chunk, dtype=params[0].dtype)
            if num_params > 0:
                # Work on a stacked copy to avoid touching original params; BF16 weights update the
                # persistent FP32 master of this rank's shard instead (ZeRO-1)
                param_chunk = (
                    group["master"]
                    if master
                    else torch.stack(params[module_idx : module_idx + num_params])
                )

                for local_idx in range(num_params):
                    (
                        cautious_wd_and_update_inplace
                        if CAUTIOUS_WD
                        else plain_wd_and_update_inplace
                    )(
                        param_chunk[local_idx],
                        v_chunk[local_idx],
                        eff_wd_cpu[local_idx],
                        eff_lr_cpu[local_idx],
                    )
            else:
                param_chunk = torch.zeros_like(v_chunk)

            updated_params[:num_params].copy_(param_chunk)
            if num_params < chunk_size:
                updated_params[num_params:].zero_()

            flat = self._pflat.get(self._group_of[params[0]])  # the params are its rows
            stacked_params = (
                torch.empty(
                    (padded_num_params, *param_shape),
                    dtype=updated_params.dtype,
                    device=updated_params.device,
                )
                if flat is None
                else flat
            )

            gather_future = dist.all_gather_into_tensor(
                stacked_params, updated_params, group=self.group, async_op=True
            )

            all_gather_infos.append(
                {
                    "gather_future": gather_future,
                    "stacked_params": stacked_params,
                    "orig_params": params,
                }
            )

        # Final pass: wait for all_gather to complete and copy results back into original parameter tensors.
        for info in all_gather_infos:
            info["gather_future"].wait()
            stacked_params = info["stacked_params"]
            orig_params = info["orig_params"]

            if stacked_params is self._pflat.get(self._group_of[orig_params[0]]):
                continue  # gathered in place
            unstacked_params = torch.unbind(stacked_params)
            for i, p in enumerate(orig_params):
                p.copy_(unstacked_params[i], non_blocking=True)


class DistAdam(torch.optim.Optimizer):
    def __init__(
        self,
        params,
        label_order: list[str],
        lr: float = 1e-3,
        betas: tuple[float, float] = (0.9, 0.999),
        eps: float = 1e-8,
        weight_decay: float = 0.01,
    ):
        self.world_size = dist.get_world_size() if dist.is_initialized() else 1
        defaults = dict(lr=lr, betas=betas, eps=eps, weight_decay=weight_decay)
        params = list(params)
        # Group by label, with explicit ordering for execution control.
        params_by_label = defaultdict(list)
        for p in params:
            params_by_label[getattr(p, "label", None)].append(p)
        param_groups = []
        for label in label_order:
            if label in params_by_label:
                param_groups.append(dict(params=params_by_label[label]))
        # include any unlabeled params at the end (processed last)
        if None in params_by_label:
            param_groups.append(dict(params=params_by_label[None]))
        super().__init__(param_groups, defaults)
        # init state: small params (numel < 1024) use full-sized state, others use sharded
        rank = dist.get_rank() if dist.is_initialized() else 0
        for p in params:
            chunk = p if p.numel() < 1024 else p[: p.size(0) // self.world_size]
            dtype = torch.float32 if getattr(p, "fp32_state", False) else torch.bfloat16
            exp_avg = torch.zeros_like(chunk, dtype=dtype, device=p.device)
            self.state[p] = dict(
                step=0, exp_avg=exp_avg, exp_avg_sq=torch.zeros_like(exp_avg)
            )
            # BF16 weight: FP32 master of this rank's slice
            if getattr(p, "master", False):
                n, w = len(chunk), getattr(p, "fp32", p)
                self.state[p]["master"] = (
                    (w if p.numel() < 1024 else w[rank * n : (rank + 1) * n])
                    .float()
                    .clone()
                )
                if hasattr(p, "fp32"):
                    del p.fp32
        # DistributedAdam implementation by @vagrawal, @akash5474
        self.should_sync = False
        self._reduce_scatter_hooks = []
        self._reduce_scatter_futures = {}
        self.register_backward_hooks()

    def register_backward_hooks(self):
        for group in self.param_groups:
            for param in group["params"]:
                self._reduce_scatter_hooks.append(
                    param.register_post_accumulate_grad_hook(self._sync_gradient)
                )

    @torch.no_grad()
    def _sync_gradient(self, param):
        if not self.should_sync:
            return

        grad = param.grad
        if getattr(
            param, "master", False
        ):  # BF16 weight: this backward's grad folded in FP32
            if any(q is param for q in _pending):
                _flush()
            if getattr(param, "main_grad", None) is not None:
                grad, param.main_grad = param.main_grad, None
        if param.numel() < 1024:
            # Small params: use all_reduce (no scatter/gather needed)
            self._reduce_scatter_futures[param] = (
                dist.all_reduce(grad, op=dist.ReduceOp.AVG, async_op=True),
                grad,
            )
        else:
            rank_size = grad.shape[0] // self.world_size
            if grad is not None:
                grad_slice = torch.empty_like(grad[:rank_size])
                self._reduce_scatter_futures[param] = (
                    dist.reduce_scatter_tensor(
                        grad_slice, grad, op=dist.ReduceOp.AVG, async_op=True
                    ),
                    grad_slice,
                )

    def copy_lm_to_embed(self):
        # run at 1/6 of training
        # by label, not group position: other Adam groups (e.g. the model track's board) may follow
        by_label = {p.label: p for g in self.param_groups for p in g["params"]}
        lm_head, embed = by_label["lm_head"], by_label["embed"]
        lm_head_state = self.state[lm_head]
        embed_state = self.state[embed]
        embed_state["step"] = lm_head_state["step"]
        embed_state["exp_avg"] = lm_head_state["exp_avg"].clone()
        embed_state["exp_avg_sq"] = lm_head_state["exp_avg_sq"].clone()
        embed.data.copy_(lm_head.data)

    @torch.compile
    @torch.no_grad()
    def step(self):
        rank = dist.get_rank()
        all_gather_futures = []  # c10d Works: Work.wait() also releases NCCL's stashed tensors

        for group in self.param_groups:
            beta1, beta2 = group["betas"]
            eps = group["eps"]
            wd = group["weight_decay"]
            for param in group["params"]:
                if param not in self._reduce_scatter_futures:
                    continue

                fut, g_slice = self._reduce_scatter_futures[param]
                fut.wait()

                is_small = param.numel() < 1024
                if is_small:
                    # Small params: g_slice is actually full grad, p_slice is full param
                    p_slice = param
                else:
                    rank_size = param.shape[0] // self.world_size
                    p_slice = param[rank * rank_size : (rank + 1) * rank_size]

                lr = group["lr"] * getattr(param, "lr_mul", 1.0)
                state = self.state[param]
                out, p_slice = p_slice, state.get("master", p_slice)

                exp_avg = state["exp_avg"]
                exp_avg_sq = state["exp_avg_sq"]
                state["step"] += 1
                t = state["step"]
                # update running averages
                exp_avg.mul_(beta1).add_(g_slice, alpha=1 - beta1)
                exp_avg_sq.mul_(beta2).addcmul_(g_slice, g_slice, value=1 - beta2)
                # bias corrections
                bias1 = 1 - beta1**t
                bias2 = 1 - beta2**t
                # compute step
                denom = exp_avg_sq.sqrt().add_(eps)
                step_size = lr * (bias2**0.5 / bias1)
                update = exp_avg.div(denom).mul_(step_size)
                # lr as weight decay schedule
                eff_weight_decay = lr * wd * getattr(param, "wd_mul", 1.0)
                if CAUTIOUS_WD:
                    mask = (update * p_slice) > 0
                    update.addcmul_(p_slice, mask, value=eff_weight_decay * lr)
                else:
                    update.add_(p_slice, alpha=eff_weight_decay * lr)

                p_slice.add_(other=update, alpha=-1.0)
                if out is not p_slice:
                    out.copy_(p_slice)

                if not is_small:
                    all_gather_futures.append(
                        dist.all_gather_into_tensor(param, out, async_op=True)
                    )

        self._reduce_scatter_futures.clear()
        for work in all_gather_futures:
            work.wait()


