# PyTorch nn.Module definitions for the model


# yarn implementation @classiclarryd
class Yarn(nn.Module):
    def __init__(self, head_dim, max_seq_len):
        super().__init__()
        self.head_dim = head_dim
        self.max_seq_len = max_seq_len
        self.fp32 = False  # model track: FP32 cos/sin tables (default BF16)
        self.full = (
            False  # model track: rotate every head dim (default: half-truncated)
        )
        self.base_scale = 0.1  # attention scale restored by reset()
        self.reset()

    def reset(self):
        quarter = self.head_dim // 4
        angular_freq = (1 / 1024) ** torch.linspace(
            0,
            1,
            steps=2 * quarter if self.full else quarter,
            dtype=torch.float32,
            device=device,
        )
        if not self.full:
            # half-truncate RoPE by @YouJiacheng (w/ base freq tuning)
            angular_freq = torch.cat([angular_freq, angular_freq.new_zeros(quarter)])
        t = torch.arange(self.max_seq_len, dtype=torch.float32, device=device)
        theta = torch.outer(t, angular_freq)
        dt = torch.float32 if self.fp32 else torch.bfloat16
        self.cos = nn.Buffer(theta.cos().to(dt), persistent=False)
        self.sin = nn.Buffer(theta.sin().to(dt), persistent=False)
        self.angular_freq = angular_freq
        # start with 0.1, inspired by 0.12 from @leloykun and learnable scalars used by @brendanh0gan https://x.com/hi_tysam/status/1879693583898591283
        self.attn_scale = self.base_scale

    def apply(self, old_window: int, new_window: int, alpha: int = 1, beta: int = 32):
        rotations = args.block_size * old_window * self.angular_freq / (2 * torch.pi)
        scaling_factor = old_window / new_window
        interpolation_weight = torch.clamp((rotations - alpha) / (beta - alpha), 0, 1)
        self.angular_freq *= scaling_factor + interpolation_weight * (
            1 - scaling_factor
        )
        t = torch.arange(
            self.max_seq_len, dtype=torch.float32, device=self.angular_freq.device
        )
        theta = torch.outer(t, self.angular_freq)
        self.cos.copy_(theta.cos())
        self.sin.copy_(theta.sin())
        self.attn_scale *= 0.2 * math.log(new_window / old_window) + 1


def rotary(x_BTHD: Tensor, cos: Tensor, sin: Tensor):
    assert cos.size(0) >= x_BTHD.size(-3)
    cos, sin = (
        cos[None, : x_BTHD.size(-3), None, :],
        sin[None, : x_BTHD.size(-3), None, :],
    )
    x = x_BTHD.to(cos.dtype)  # FP32 tables rotate in FP32; a no-op for the default BF16
    x1, x2 = x.chunk(2, dim=-1)
    y1 = x1 * cos + x2 * sin
    y2 = x1 * (-sin) + x2 * cos
    return torch.cat((y1, y2), 3).type_as(x_BTHD)


@dataclass
class AttnArgs:
    ve: torch.Tensor
    sa_lambdas: torch.Tensor
    seqlens: torch.Tensor
    bm_size: int
    cos: torch.Tensor
    sin: torch.Tensor
    attn_scale: float
    key_offset: bool


# Attention backend is supplied by modded_medium.py.


class CausalSelfAttention(nn.Module):
    def __init__(self, dim: int, head_dim: int, num_heads: int, layer_idx: int):
        super().__init__()
        self.num_heads = num_heads
        self.head_dim = head_dim
        self.dim = dim
        self.hdim = num_heads * head_dim
        self.qk_norm = self.gates = True  # model-track ablations
        self.diff = None  # modded_diffattn.DiffLambda: differential attention

        assert self.hdim == self.dim, "num_heads * head_dim must equal model_dim"
        std = self.dim**-0.5
        bound = (3**0.5) * std  # improved init scale by @YouJiacheng
        # merged QKVO weights: suggested by many, implemented by @fernbear.bsky.social, and further improved by @YouJiacheng
        # https://x.com/hi_tysam/status/1879699187107033311
        # Simplified layout by @chrisjmccormick
        self.qkvo_w = nn.Parameter(torch.empty(self.dim * 4, self.hdim))
        # label all modules for explicit optimizer grouping
        self.qkvo_w.label = "attn"

        with torch.no_grad():
            self.qkvo_w[: self.dim * 3].uniform_(-bound, bound)  # init QKV weights
            self.qkvo_w[self.dim * 3 :].zero_()  # init O weights to zero

        # sparse gated attention to enable context based no-op by @classiclarryd
        self.attn_gate = CastedLinear(16, num_heads)
        self.attn_gate.weight.label = "attn_gate"
        self.attn_gate.weight.lr_mul = 0.1

        # only include gates on layers with value embeds used on forward pass
        if layer_idx < min(
            5, args.num_layers // 2
        ) or layer_idx >= args.num_layers - min(5, args.num_layers // 2):
            self.value_embed_gate = CastedLinear(16, num_heads)
            self.value_embed_gate.weight.label = "value_embed_gate"
            self.value_embed_gate.weight.lr_mul = 0.1

    def forward(self, x: Tensor, attn_args: AttnArgs):
        B, T = x.size(0), x.size(1)  # batch size, sequence length
        assert B == 1, "varlen sequences requires B == 1"
        assert T % 16 == 0
        # unpack attention args
        cos, sin = attn_args.cos, attn_args.sin
        ve, sa_lambdas, key_offset = (
            attn_args.ve,
            attn_args.sa_lambdas,
            attn_args.key_offset,
        )
        seqlens, attn_scale, bm_size = (
            attn_args.seqlens,
            attn_args.attn_scale,
            attn_args.bm_size,
        )

        q, k, v = (
            F.linear(x, sa_lambdas[0] * self.qkvo_w[: self.dim * 3].type_as(x))
            .view(B, T, 3 * self.num_heads, self.head_dim)
            .chunk(3, dim=-2)
        )
        if self.qk_norm:
            q, k = norm(q), norm(k)  # QK norm @Grad62304977
        q, k = rotary(q, cos, sin), rotary(k, cos, sin)
        if key_offset:
            # shift keys forward for the stationary head dims. Enables 1-layer induction.
            same = seqlens.same_previous[1:][None, :, None, None]
            # Keep a game's first key intact; never import the preceding game.
            k = k.clone()
            k[:, 1:, :, self.head_dim // 4 : self.head_dim // 2] = torch.where(
                same,
                k[:, :-1, :, self.head_dim // 4 : self.head_dim // 2].clone(),
                k[:, 1:, :, self.head_dim // 4 : self.head_dim // 2],
            )
            k[:, 1:, :, 3 * self.head_dim // 4 :] = torch.where(
                same,
                k[:, :-1, :, 3 * self.head_dim // 4 :].clone(),
                k[:, 1:, :, 3 * self.head_dim // 4 :],
            )
        if ve is not None:
            ve_gate_out = 2 * torch.sigmoid(
                self.value_embed_gate(x[..., : self.value_embed_gate.weight.size(-1)])
            ).view(B, T, self.num_heads, 1)
            if not self.gates:  # identity gate; the gate weight keeps a (zero) gradient
                ve_gate_out = ve_gate_out * 0 + 1
            v = v + ve_gate_out * ve.view_as(v)  # @ KoszarskyB & @Grad62304977

        max_len = (
            args.train_max_seq_len
            if self.training
            else (args.val_batch_size // (grad_accum_steps * world_size))
        )

        # use flash_attn over flex_attn @varunneal. flash_attn_varlen suggested by @YouJiacheng
        attend = lambda q, k, v: medium_attention(q, k, v, seqlens, bm_size, attn_scale)
        y = (
            attend(q, k, v)
            if self.diff is None
            else diff_attention(q, k, v, self.diff(), self.diff.init, attend)
        )
        y = y.view(B, T, self.num_heads, self.head_dim)
        gate = torch.sigmoid(
            self.attn_gate(x[..., : self.attn_gate.weight.size(-1)])
        ).view(B, T, self.num_heads, 1)
        y = y * (
            gate if self.gates else gate * 0 + 0.5
        )  # sigma(0): the default gate at init
        y = y.contiguous().view(
            B, T, self.num_heads * self.head_dim
        )  # re-assemble all head outputs side by side
        y = F.linear(
            y, sa_lambdas[1] * self.qkvo_w[self.dim * 3 :].type_as(y)
        )  # sa_lambdas[1] pre-multiplied to O @shenberg
        return y


class MLP(nn.Module):
    def __init__(self, dim: int, kind: str = "relu2"):
        super().__init__()
        self.kind = kind  # relu2 | gelu | swiglu (model track)
        hdim = swiglu_hidden(dim) if kind == "swiglu" else 4 * dim
        # Transposed layout to match attention weights
        self.c_fc = nn.Parameter(
            torch.empty(hdim * (2 if kind == "swiglu" else 1), dim)
        )
        self.c_proj = nn.Parameter(torch.empty(hdim, dim))
        # label all modules for explicit optimizer grouping; NorMuon stacks a label's params, so
        # SwiGLU's differently shaped projection gets its own label
        self.c_fc.label = "mlp"
        self.c_proj.label = "mlp_proj" if kind == "swiglu" else "mlp"
        self.c_proj.lr_mul = 2.0

        std = 0.5 * (dim**-0.5)
        bound = (3**0.5) * std  # improved init scale by @YouJiacheng
        with torch.no_grad():
            self.c_fc.uniform_(-bound, bound)
            self.c_proj.zero_()  # zero init suggested by @Grad62304977

    def forward(self, x: Tensor):
        x = F.linear(x, self.c_fc.type_as(x))
        if self.kind == "swiglu":
            a, b = x.chunk(2, dim=-1)
            x = F.silu(a) * b
        elif self.kind == "gelu":
            x = F.gelu(x)
        else:
            x = F.relu(
                x
            ).square()  # https://arxiv.org/abs/2109.08668v2; ~1-2% better than GELU; suggested by @SKYLINEZ007 and @Grad62304977
        x = F.linear(x, self.c_proj.T.type_as(x))
        return x


class Block(nn.Module):
    def __init__(
        self,
        dim: int,
        head_dim: int,
        num_heads: int,
        layer_idx: int,
        mlp: str = "relu2",
        moe: tuple | None = None,
    ):
        super().__init__()
        self.attn = CausalSelfAttention(dim, head_dim, num_heads, layer_idx)
        # model track: MoE (modded_arch.moe_dims) after a dense first layer, as in DeepSeek-V3
        self.mlp = MoE(dim, *moe) if moe and layer_idx else MLP(dim, mlp)

    def forward(self, x: Tensor, attn_args: AttnArgs):
        if CKPT == "block" and self.training:
            return torch.utils.checkpoint.checkpoint(
                self._forward, x, attn_args, use_reentrant=False
            )
        return self._forward(x, attn_args)

    def _forward(self, x: Tensor, attn_args: AttnArgs):
        x = x + self.attn(norm(x), attn_args)
        if CKPT == "mlp" and self.training:
            return x + torch.utils.checkpoint.checkpoint(
                lambda h: self.mlp(norm(h)), x, use_reentrant=False
            )
        return x + self.mlp(norm(x))


# -----------------------------------------------------------------------------
# The main model


def next_multiple_of_n(v: float | int, *, n: int):
    return next(x for x in range(n, int(v) + 1 + n, n) if x >= v)


@dataclass
class ForwardScheduleConfig:
    mtp_weights: torch.Tensor
    ws_short: int
    ws_long: int


class GPT(nn.Module):
    def __init__(
        self,
        vocab_size: int,
        num_layers: int,
        num_heads: int,
        head_dim: int,
        model_dim: int,
        max_seq_len: int,
        mlp: str = "relu2",
        untie_ve: bool = False,
        moe: tuple | None = None,
    ):
        super().__init__()
        self.num_layers = num_layers
        vocab_size = next_multiple_of_n(vocab_size, n=128)

        self.smear_gate = CastedLinear(16, 1)
        self.smear_gate.weight.label = "smear_gate"
        self.smear_gate.weight.lr_mul = 0.01
        self.smear_gate.weight.wd_mul = 0.0

        self.skip_gates = nn.ModuleList([CastedLinear(16, 1) for _ in range(3)])
        for sg in self.skip_gates:
            sg.weight.label = "skip_gate"
            sg.weight.lr_mul = 0.01
            sg.weight.wd_mul = 0.0

        # token value embeddings by @KoszarskyB - inspired by @Grad62304977's value residual implementation following https://arxiv.org/abs/2410.17897
        # value embedding code simplification inspired by @ragulpr https://github.com/KellerJordan/modded-nanogpt/pull/78
        self.value_embeds = nn.ModuleList(
            [
                nn.Embedding(vocab_size, model_dim)
                for _ in range(min(5, num_layers // 2) * (2 if untie_ve else 1))
            ]
        )
        self.untie_ve = untie_ve  # model track: one table per value-embedding layer
        for embed in self.value_embeds:
            nn.init.zeros_(embed.weight)
        for ve in self.value_embeds:
            ve.weight.label = "value_embed"
        self.blocks = nn.ModuleList(
            [
                Block(model_dim, head_dim, num_heads, i, mlp, moe)
                for i in range(num_layers)
            ]
        )
        self.yarn = Yarn(head_dim, max_seq_len)
        # there are only 50257 unique GPT-2 tokens; we extend to nearest multiple of 128 for efficiency.
        # suggested to me by @Grad62304977. this originates from Karpathy's experiments.
        use_fp8 = not os.environ.get("DISABLE_FP8", False)

        self.lm_head = CastedLinear(
            model_dim,
            vocab_size,
            use_fp8=use_fp8,
            x_s=100 / 448,
            w_s=1.6 / 448,
            grad_s=0.75 / 448,
        )
        nn.init.normal_(self.lm_head.weight, mean=0, std=0.005)
        self.lm_head.weight.label = "lm_head"

        self.embed = nn.Embedding(vocab_size, model_dim)
        self.embed.weight.label = "embed"

        self.embed2 = nn.Embedding(vocab_size, model_dim)
        self.embed2.weight.label = "embed2"

        # x0_lambdas separated out for different optimizer treatment (no beta smoothing)
        self.x0_lambdas = nn.Parameter(torch.zeros(2 * num_layers))
        self.x0_lambdas.label = "x0_lambdas"
        self.x0_lambdas.lr_mul = 5.0
        self.x0_lambdas.wd_mul = 0.0

        pad = (
            -num_layers * 3 - 5
        ) % dist.get_world_size()  # updated: 3*num_layers instead of 4*
        self.scalars = nn.Parameter(
            torch.cat(
                [
                    1.05
                    * torch.ones(
                        num_layers
                    ),  # resid lambdas. 1.05 init such that layer i weight is i^(num_layers-i).
                    *[
                        torch.tensor([0.5, 1.0]) for _ in range(num_layers)
                    ],  # SA lambdas
                    torch.zeros(1),  # smear_lambda
                    0.5 * torch.ones(1),  # backout_lambda
                    -1.5 * torch.ones(3),  # skip_lambdas -> σ(-1.5) ≈ 0.18
                    torch.ones(pad),
                ]
            )
        )

        self.scalars.label = "scalars"
        # set learning rates
        for param in self.value_embeds.parameters():
            param.lr_mul = 75.0
            param.wd_mul = 5.0
        for param in self.embed.parameters():
            param.wd_mul = 150.0
        for param in self.embed2.parameters():
            param.lr_mul = 75.0
            param.wd_mul = 5.0
        for param in self.lm_head.parameters():
            param.wd_mul = 150.0
        self.scalars.lr_mul = 5.0
        self.scalars.wd_mul = 0.0

        # start training with tied embed/lm_head
        self.split_embed = False

        # Embedding of the mover's time-left bucket (0 = no clock, fixed at zero), added to the token
        # embedding when use_clock. Zero init keeps a fresh model clock-blind; created last so every
        # other parameter's initialization is unchanged.
        self.use_clock = False
        self.clock_embed = nn.Embedding(64, model_dim, padding_idx=0)
        nn.init.zeros_(self.clock_embed.weight)
        self.clock_embed.weight.label = "embed2"
        self.clock_embed.weight.lr_mul = 75.0
        self.clock_embed.weight.wd_mul = 5.0
        # Embedding of the mover's rating bucket (50 Elo wide, 0 = none), same treatment as the clock.
        self.use_elo = False
        self.elo_embed = nn.Embedding(64, model_dim, padding_idx=0)
        nn.init.zeros_(self.elo_embed.weight)
        self.elo_embed.weight.label = "embed2"
        self.elo_embed.weight.lr_mul = 75.0
        self.elo_embed.weight.wd_mul = 5.0
        # Continuous clock features (use_feats): three raw-seconds channels -> 54 log-Fourier
        # features -> model_dim, zero init; rows 54..63 pad dim 0 for optimizer sharding.
        self.use_feats = False
        self.feat_embed = nn.Embedding(64, model_dim)
        nn.init.zeros_(self.feat_embed.weight)
        self.feat_embed.weight.label = "embed2"
        self.feat_embed.weight.lr_mul = 75.0
        self.feat_embed.weight.wd_mul = 5.0
        # Model-track ablations of inherited speedrun components (default on).
        self.use_value_embeds = self.use_skips = self.use_smear = True
        self.doc_rope = (
            False  # rotary position = index in the game instead of the packed batch
        )
        self.use_x0 = self.use_embed2 = self.softcap = self.use_key_offset = True
        self.aux_detach = (
            None  # first aux-head row, when those rows get stop-gradient features
        )
        self.fp32_embed = False  # FP32 embedding/head state: cast lookups to BF16
        self.board = None  # modded_board branch, added at every position when set

    def forward(
        self,
        input_seq: Tensor,
        target_seq: Tensor,
        seqlens: Tensor,
        schedule_cfg: ForwardScheduleConfig,
        clock_seq: Tensor | None = None,
        elo_seq: Tensor | None = None,
        feat_seq: Tensor | None = None,
    ):
        assert input_seq.ndim == 1

        # unpack schedule_cfg
        mtp_weights, ws_short, ws_long = (
            schedule_cfg.mtp_weights,
            schedule_cfg.ws_short,
            schedule_cfg.ws_long,
        )

        # set configs
        skip_connections = []
        skip_in = [i * self.num_layers // 16 for i in (2, 4, 6)]
        skip_out = [9 * self.num_layers // 16 + i for i in range(3)]
        x_backout = None
        backout_layer = skip_out[-1]

        # set lambdas
        resid_lambdas = self.scalars[: 1 * self.num_layers]
        x0_lambdas = self.x0_lambdas.view(-1, 2)
        if not self.use_x0:  # drop x0 re-injection; keep the x02 column
            x0_lambdas = torch.stack((x0_lambdas[:, 0] * 0, x0_lambdas[:, 1]), 1)
        sa_lambdas = self.scalars[1 * self.num_layers : 3 * self.num_layers].view(-1, 2)
        smear_lambda = self.scalars[3 * self.num_layers]
        backout_lambda = self.scalars[3 * self.num_layers + 1]
        skip_lambdas = self.scalars[3 * self.num_layers + 2 : 3 * self.num_layers + 5]

        # set block masks and key shift
        short_bm = ws_short * args.block_size
        long_bm = ws_long * args.block_size
        long_layers = {round(i * (self.num_layers - 1) / 15) for i in (0, 4, 11, 15)}
        bm_sizes = [
            long_bm if i in long_layers else short_bm for i in range(self.num_layers)
        ]
        assert len(bm_sizes) == self.num_layers
        key_offset = [
            b == long_bm and self.use_key_offset for b in bm_sizes
        ]  # apply partial key offset to long windows

        # weight-tied: use lm_head.weight for embedding lookup (or separate embed after split)
        if self.split_embed:
            x = self.embed(input_seq)
        else:
            x = F.embedding(input_seq, self.lm_head.weight)
        if self.fp32_embed:
            x = x.bfloat16()
        if self.use_clock:
            ids = torch.zeros_like(input_seq) if clock_seq is None else clock_seq
            x = x + self.clock_embed(ids)
        if self.use_elo:
            ids = torch.zeros_like(input_seq) if elo_seq is None else elo_seq
            x = x + self.elo_embed(ids)
        if self.use_feats and feat_seq is not None:
            t = feat_seq[:, : self.use_feats].float()
            v = torch.log1p(t.clamp(min=0))[..., None] / 10
            w = torch.pi * 2.0 ** torch.arange(8, device=t.device)
            f = torch.cat(
                (torch.sin(v * w), torch.cos(v * w), v, torch.ones_like(v)), -1
            )
            f = (f * (t >= 0)[..., None]).flatten(1)  # absent values (-1) give zeros
            f = F.pad(f, (0, 64 - f.shape[1]))
            x = x + f.type_as(x) @ self.feat_embed.weight.type_as(x)
        if self.board is not None:
            x = x + self.board(seqlens.board, x.dtype)
        ve = [value_embed(input_seq) for value_embed in self.value_embeds]
        if self.fp32_embed:
            ve = [v.bfloat16() for v in ve]
        if (
            not self.use_value_embeds
        ):  # ablated by zero so every parameter keeps a gradient
            ve = [v * 0 for v in ve]
        # 012 ... 012 structure on token value embeddings by @YouJiacheng, improved on @leloykun's U-net structure
        # dropping first layer updates this to .12 ... 012
        k = len(ve) // 2 if self.untie_ve else len(ve)
        ve = ve[:k] + [None] * (self.num_layers - 2 * k) + ve[-k:]
        assert len(ve) == self.num_layers

        # smear token embed forward 1 position @classiclarryd
        smear_gate_out = smear_lambda * torch.sigmoid(
            self.smear_gate(x[1:, : self.smear_gate.weight.size(-1)])
        )
        if not self.use_smear:
            smear_gate_out = smear_gate_out * 0
        x = torch.cat(
            [x[:1], x[1:] + smear_gate_out * x[:-1] * seqlens.same_previous[1:, None]]
        )
        x = x0 = norm(x[None])

        e2 = self.embed2(input_seq)
        x02 = norm((e2.bfloat16() if self.fp32_embed else e2)[None])
        if not self.use_embed2:
            x02 = x02 * 0

        cos, sin = self.yarn.cos, self.yarn.sin
        if self.doc_rope:
            cos, sin = cos[seqlens.positions], sin[seqlens.positions]
        skip_idx = 0
        for i in range(self.num_layers):
            attn_args = AttnArgs(
                ve=ve[i],
                sa_lambdas=sa_lambdas[i],
                seqlens=seqlens,
                bm_size=bm_sizes[i],
                cos=cos,
                sin=sin,
                attn_scale=self.yarn.attn_scale,
                key_offset=key_offset[i],
            )
            if i in skip_out:
                skip_gate_out = (
                    torch.sigmoid(skip_lambdas[skip_idx])
                    * 2
                    * torch.sigmoid(
                        self.skip_gates[skip_idx](
                            x0[..., : self.skip_gates[skip_idx].weight.size(-1)]
                        )
                    )
                )
                skip_idx += 1
                skip = skip_connections.pop()
                x = x + skip_gate_out * (skip if self.use_skips else skip * 0)
            if i == 0:
                x = (resid_lambdas[0] + x0_lambdas[0, 0]) * x + x0_lambdas[0, 1] * x02
            else:
                x = (
                    resid_lambdas[i] * x
                    + x0_lambdas[i, 0] * x0
                    + x0_lambdas[i, 1] * x02
                )
            x = self.blocks[i](x, attn_args)
            if i in skip_in:
                skip_connections.append(x)
            if i == backout_layer:
                x_backout = x

        # back out contributions from first 2/3 layers that are only required for downstream context and not direct prediction
        x -= backout_lambda * (x_backout if self.use_skips else x_backout * 0)
        x = norm(x)

        logits = self.lm_head(x)
        if (
            self.aux_detach
        ):  # head rows from this index on (the aux heads) see stop-gradient features
            k = self.aux_detach
            aux = F.linear(x.detach(), self.lm_head.weight[k:].type_as(x))
            logits = torch.cat((logits[..., :k], aux), -1)
        if not self.softcap:
            return logits
        return 23 * torch.sigmoid((logits + 5) / 7.5)


# -----------------------------------------------------------------------------
# Distributed data loader


def get_bs(step: int):
    if step >= args.num_scheduled_iterations:
        return args.train_bs_extension
    x = step / args.num_scheduled_iterations
    bs_idx = int(len(args.train_bs_schedule) * x)
    return args.train_bs_schedule[bs_idx]


def get_ws(step: int):
    # set short window size to half of long window size
    # Higher ws on "extension" steps
    if step >= args.num_scheduled_iterations:
        return args.ws_final // 2, args.ws_final
    x = step / args.num_scheduled_iterations
    assert 0 <= x < 1
    ws_idx = int(len(args.ws_schedule) * x)
    return min(11, args.ws_schedule[ws_idx] // 2), args.ws_schedule[ws_idx]


# learning rate schedule: tied to batch size schedule, with cooldown at the end.
def get_lr(step: int):
    if step > args.num_scheduled_iterations:
        return 0.1
    lr_max = 1.0
    x = step / args.num_scheduled_iterations
    if x > 1 / 12:
        lr_max = 1.52  # (16/8)**0.6
    if x > 2 / 12:
        lr_max = 1.73  # (24/8)**0.5
    if x > 3 / 12:
        lr_max = 2.0
    if x >= 1 - args.cooldown_frac:
        w = (1 - x) / args.cooldown_frac
        lr = lr_max * w + (1 - w) * 0.1
        return lr
    return lr_max


def get_muon_momentum(
    step: int,
    muon_warmup_steps=300,
    muon_cooldown_steps=50,
    momentum_min=0.85,
    momentum_max=0.95,
):
    # warmup phase: linearly increase momentum from min to max
    # cooldown phase: linearly decrease momentum from max to min
    momentum_cd_start = args.num_iterations - muon_cooldown_steps
    if step < muon_warmup_steps:
        frac = step / muon_warmup_steps
        momentum = momentum_min + frac * (momentum_max - momentum_min)
    elif step > momentum_cd_start:
        frac = (step - momentum_cd_start) / muon_cooldown_steps
        momentum = momentum_max - frac * (momentum_max - momentum_min)
    else:
        momentum = momentum_max
    return momentum


class TrainingManager:
    """
    Manages three optimizers for Adam embed/lm_head, Adam scalars, and Muon weight matrices.
    Notable Features:
        1. Scalars are given higher momentum terms to smooth learning @ChrisJMcCormick
        2. Scalar weights are temporarily frozen during batch size or window size updates @ChrisJMcCormick
        3. Adam optimizers are only stepped on odd steps @classiclarryd
        4. Adam optimizers have hooks to start gradient communication during backwards pass @akash5474
        5. Muon has a linear momentum warmup and cooldown schedule
        6. Learning rates follow a linear decay schedule
        7. Embed/lm_head weights and optimizer state splits at 2/3 of training @classiclarryd

    Manages model architecture, data, and target that changes during training
    Notable Features:
        1. Multi Token Prediction schedule of [1, 0.5, 0.25->0] -> [1, 0.5->0] -> [1] @varunneal
        2. Sliding Attention window schedule of [1,3] -> [3,7] -> [5,11] -> [6,13]
        3. YaRN updates to RoPE on window changes
        4. Split embed and lm head at 2/3 of training
        5. Batch size schedule of 8 -> 16 -> 24
        6. Post training extension of long windows from 13 to 20
    """

    def __init__(self, model):
        self.mtp_weights_schedule = self._build_mtp_schedule()
        self.model = model

        adam_labels = [
            "lm_head",
            "value_embed",
            "smear_gate",
            "skip_gate",
            "x0_lambdas",
            "embed2",
            "embed",
            "board",
            "router",
            "diff",
        ]
        scalar_labels = ["scalars"]
        muon_labels = ["attn_gate", "value_embed_gate", "attn", "mlp", "mlp_proj"]
        muon_labels += ["moe", "moe_up", "mlp_shared", "mlp_shared_up"]
        self.moe = [m for m in model.modules() if isinstance(m, MoE)]
        # model track: AdamW (base lr model.matrix_adam) for the attention / MLP matrices
        matrix_labels = (
            ["attn", "mlp", "mlp_proj"] if getattr(model, "matrix_adam", 0) else []
        )
        muon_labels = [l for l in muon_labels if l not in matrix_labels]
        matrix_params = [
            p for p in model.parameters() if getattr(p, "label", None) in matrix_labels
        ]
        adam_params = [
            p for p in model.parameters() if getattr(p, "label", None) in adam_labels
        ]
        scalar_params = [
            p for p in model.parameters() if getattr(p, "label", None) in scalar_labels
        ]
        muon_params = [
            p for p in model.parameters() if getattr(p, "label", None) in muon_labels
        ]
        local_labels = ["moe_sh", "moe_up_sh"]  # sharded experts: rank-local NorMuon
        local_params = [
            p for p in model.parameters() if getattr(p, "label", None) in local_labels
        ]
        assert set(getattr(p, "label", None) for p in model.parameters()) <= set(
            adam_labels + scalar_labels + muon_labels + matrix_labels + local_labels
        ), "All params must have label"

        self.adam_opt = DistAdam(
            adam_params,
            adam_labels,
            lr=0.004,
            betas=(0.8, 0.95),
            eps=1e-8,
            weight_decay=0.005,
        )
        self.scalar_opt = DistAdam(
            scalar_params,
            scalar_labels,
            lr=0.008,
            betas=(0.9, 0.99),
            eps=1e-8,
            weight_decay=0.005,
        )
        self.muon_opt = NorMuon(
            muon_params, lr=0.015, momentum=0.95, beta2=0.95, weight_decay=1.2
        )
        self.optimizers = [self.adam_opt, self.scalar_opt, self.muon_opt]
        if local_params:
            world = dist.get_world_size()
            groups = [dist.new_group([r]) for r in range(world)]  # collective: every rank makes all
            self.local_opt = NorMuon(
                local_params, lr=0.015, momentum=0.95, beta2=0.95, weight_decay=1.2,
                group=groups[dist.get_rank()],
            )  # fmt: skip
            self.optimizers.append(self.local_opt)
        if matrix_params:
            self.matrix_opt = DistAdam(
                matrix_params,
                matrix_labels,
                lr=model.matrix_adam,
                betas=(0.9, 0.95),
                eps=1e-8,
                weight_decay=model.matrix_wd,
            )
            self.optimizers.append(self.matrix_opt)
        # split after odd number step
        self.split_step = (
            math.ceil(args.split_embed_frac * args.num_scheduled_iterations) | 1
        )

        # set defaults
        for opt in self.optimizers:
            opt.freeze_timer = 0
            opt.odd_step_only = False
            opt.should_sync = True
            for group in opt.param_groups:
                group["initial_lr"] = group["lr"]

        # on even steps, only step Muon params
        self.adam_opt.odd_step_only = True
        self.scalar_opt.odd_step_only = True

        self.reset()

    def _build_mtp_schedule(self):
        # Precompute MTP weights for all steps to avoid tensor allocation during training
        # Schedule: [1, 0.5, 0.25->0] -> [1, 0.5->0] -> [1]
        mtp_weights_schedule = []
        for s in range(args.num_iterations + 1):
            x = s / (args.num_scheduled_iterations / 4)
            if x < 1 / 3:
                w = [1.0, 0.5, 0.25 * (1 - 3 * x)]
            elif x < 2 / 3:
                w = [1.0, 0.5 * (1 - (3 * x - 1))]
            else:
                w = [1.0]
            mtp_weights_schedule.append(torch.tensor(w, device=device))
        return mtp_weights_schedule

    def apply_final_ws_ext(self):
        self.ws_long = args.ws_validate_post_yarn_ext

    def get_forward_args(self):
        return ForwardScheduleConfig(
            mtp_weights=self.mtp_weights, ws_short=self.ws_short, ws_long=self.ws_long
        )

    def _is_active_step(self, opt, step: int):
        return (opt.odd_step_only and step % 2 == 1) or not opt.odd_step_only

    def get_transition_steps(self):
        transition_steps = [0]
        ws_short, ws_long = get_ws(0)
        for step in range(1, args.num_iterations):
            ws_short, new_ws_long = get_ws(step)
            if new_ws_long != ws_long:
                transition_steps.append(step)
                ws_long = new_ws_long
        return transition_steps

    def advance_schedule(self, step: int):
        self.ws_short, new_ws_long = get_ws(step)
        # only apply yarn for first few
        if new_ws_long != self.ws_long and new_ws_long <= 13:
            self.model.yarn.apply(self.ws_long, new_ws_long)

        new_batch_size = get_bs(step)
        if new_batch_size != self.batch_size:
            self.train_loader_send_args = (
                new_batch_size,
                args.train_max_seq_len,
                grad_accum_steps,
            )
        else:
            self.train_loader_send_args = None

        self.ws_long = new_ws_long
        self.mtp_weights = self.mtp_weights_schedule[step]

    def step_optimizers(self, step: int):
        step_lr = get_lr(step)
        muon_momentum = get_muon_momentum(step)
        for opt in (self.muon_opt, getattr(self, "local_opt", None)):
            for group in opt.param_groups if opt else ():
                group["momentum"] = muon_momentum

        for opt in self.optimizers:
            if opt.freeze_timer > 0:
                opt.freeze_timer -= 1
                opt.zero_grad(set_to_none=True)
            else:
                if self._is_active_step(opt, step):
                    for group in opt.param_groups:
                        group["lr"] = group["initial_lr"] * step_lr
                    opt.step()
                    opt.zero_grad(set_to_none=True)
                    if isinstance(opt, DistAdam):  # re-armed on the last micro-batch
                        opt.should_sync = False

        # prop bias rule: full speed for the first 80% of training, then linearly to 0 at the end
        # (DeepSeek-V3 stops bias updates in its final phase)
        if self.moe:
            n = args.num_iterations
            scale = min(1.0, max(0.0, (n - step) / (0.2 * n)))
            for m in self.moe:
                m.rebalance(scale)

        if step == self.split_step:
            self.adam_opt.copy_lm_to_embed()
            self.model.split_embed = True

    def start_transition(self, freeze_count=40):
        # freeze scalar weights during transition
        self.scalar_opt.freeze_timer = freeze_count

    def activate_hooks(self, step: int):
        for opt in self.optimizers:
            if self._is_active_step(opt, step):
                opt.should_sync = True

    def reset(self, state=None):
        if state is not None:
            for opt, opt_state in zip(self.optimizers, state):
                opt.should_sync = False
                opt.load_state_dict(opt_state)

        # muon momentum buffers not in state dict
        self.muon_opt.reset()
        if hasattr(self, "local_opt"):
            self.local_opt.reset()
        self.model.split_embed = False

        self.ws_short, self.ws_long = get_ws(0)
        self.batch_size = get_bs(0)
        self.model.yarn.reset()

    def get_state(self):
        return [copy.deepcopy(opt.state_dict()) for opt in self.optimizers]


